import{_ as t,o as s,c as a,a2 as d}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"自动跟进仓库更新","description":"用 UTC 计划轮询或签名 Webhook 检查新提交，并确认事实刷新已经排队和完成。","frontmatter":{"page_id":"guide-automation","description":"用 UTC 计划轮询或签名 Webhook 检查新提交，并确认事实刷新已经排队和完成。"},"headers":[],"relativePath":"guide/automation.md","filePath":"guide/automation.md","lastUpdated":1786290726000}'),o={name:"guide/automation.md"};function i(r,e,n,c,p,l){return s(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="自动跟进仓库更新" tabindex="-1">自动跟进仓库更新 <a class="header-anchor" href="#自动跟进仓库更新" aria-label="Permalink to &quot;自动跟进仓库更新&quot;">​</a></h1><p>Ershu 有两种自动检查仓库提交的方式：独立 Poller 按 UTC Cron 计划拉取仓库，或外部系统调用签名 Webhook。两条路径都会先判断提交是否已经分析或排队，只有发现需要处理的提交才创建事实刷新任务。</p><p>自动触发只更新目录、代码索引、知识关系和搜索索引，不会重新生成 AI 文档。需要文档跟上新提交时，应另行发起支持文档生成的分析任务。</p><h2 id="先选择触发方式" tabindex="-1">先选择触发方式 <a class="header-anchor" href="#先选择触发方式" aria-label="Permalink to &quot;先选择触发方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>适合什么情况</th><th>额外依赖</th><th>成功信号</th></tr></thead><tbody><tr><td>计划轮询</td><td>仓库系统不能主动通知 Ershu，或希望由 Ershu 控制检查节奏</td><td>持续运行的 <code>ershu-api-poller</code> 和 Redis</td><td>Poller 审计记录出现，响应结果为 <code>queued</code> 或带明确原因的 <code>skipped</code></td></tr><tr><td>签名 Webhook</td><td>外部系统能在提交发生时发送自定义 HTTP 请求</td><td>能按 Ershu 格式计算 HMAC 的发送端</td><td>Webhook 返回 HTTP <code>202</code>，正文为 <code>queued</code> 或带原因的 <code>skipped</code></td></tr><tr><td>手动轮询</td><td>配置后立即验证仓库访问和变化判断</td><td>已登录且有项目管理权限</td><td>手动轮询接口返回 HTTP <code>202</code> 和可解释结果</td></tr></tbody></table><p>不论哪种方式，实际工作都由 Worker 从 PostgreSQL 队列领取。Worker 未运行时，<code>queued</code> 只表示任务已经入队。</p><h2 id="配置计划轮询" tabindex="-1">配置计划轮询 <a class="header-anchor" href="#配置计划轮询" aria-label="Permalink to &quot;配置计划轮询&quot;">​</a></h2><p>在仓库触发设置中先填写 <code>poll_cron</code>，再启用 <code>poll_enabled</code>。计划必须是合法的五段 Cron 表达式，并统一按 UTC 解释。例如，<code>0 * * * *</code> 表示每个 UTC 整点检查一次。</p><p>API 对应的管理路径是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATCH /api/v1/projects/{project_id}/repositories/{repository_id}/triggers</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>请求含有敏感的登录状态与 CSRF 保护，通常应通过网页设置。启用时若没有计划，API 会拒绝保存。</p><p>随后单独运行 Poller。下面是建议命令，本任务没有在你的环境中执行它：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api-poller</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Poller 的默认行为是每 <code>30</code> 秒扫描一次，到期仓库每批最多 <code>100</code> 个。它使用 Redis 的可续租锁，默认租期 <code>120</code> 秒，同一时刻只有取得锁的实例执行扫描。相关范围见<a href="./../configuration/environment-reference">环境变量参考</a>。</p><p>想立即做一次诊断性扫描时，可以使用建议命令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api-poller</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --once</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>命令以退出码 <code>0</code> 结束只说明本轮进程没有未处理错误。是否发现更新，要继续看仓库的最近轮询时间、审计记录和新任务状态。</p><h2 id="配置签名-webhook" tabindex="-1">配置签名 Webhook <a class="header-anchor" href="#配置签名-webhook" aria-label="Permalink to &quot;配置签名 Webhook&quot;">​</a></h2><p>在仓库触发设置中先保存一个至少 <code>16</code> 个字符的 <code>webhook_secret</code>，再启用 <code>webhook_enabled</code>。读取设置时只会返回 <code>has_webhook_secret</code>，不会回传密钥原文。</p><p>Webhook 地址为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/webhooks/repositories/{repository_id}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>请求正文是 JSON，可包含：</p><table tabindex="0"><thead><tr><th>字段</th><th>约束</th><th>用途</th></tr></thead><tbody><tr><td><code>branch</code></td><td>可省略</td><td>指定要记录的分支</td></tr><tr><td><code>commit_sha</code></td><td>可省略；必须是 40 或 64 位十六进制</td><td>指定要刷新的准确提交</td></tr><tr><td><code>event</code></td><td>可省略；最多 64 个字符</td><td>在结果和审计记录中说明触发原因</td></tr></tbody></table><p>发送端必须保留最终发送的原始正文字节，并构造三个请求头：</p><table tabindex="0"><thead><tr><th>请求头</th><th>内容</th></tr></thead><tbody><tr><td><code>X-Ershu-Webhook-Timestamp</code></td><td>当前 Unix 时间；服务端允许与数据库时间相差最多 <code>300</code> 秒</td></tr><tr><td><code>X-Ershu-Webhook-Nonce</code></td><td>本次请求的唯一值；最多 <code>255</code> 个字符，不能含冒号或换行</td></tr><tr><td><code>X-Ershu-Webhook-Signature</code></td><td>下述内容的 HMAC-SHA256 小写十六进制摘要</td></tr></tbody></table><p>签名消息必须严格按字节拼接：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UTF-8(timestamp) + NUL + UTF-8(nonce) + NUL + raw_request_body</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>HMAC 密钥就是仓库中保存的 <code>webhook_secret</code>。签名覆盖的是最终发送字节；计算后重新格式化 JSON 会导致认证失败。相同 nonce 在保护窗口内再次使用也会被拒绝。</p><p>以下请求只展示正文形状，不包含可直接使用的签名，因此不能原样执行：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;branch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;commit_sha&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;40-or-64-character-commit&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;push&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="读懂触发结果" tabindex="-1">读懂触发结果 <a class="header-anchor" href="#读懂触发结果" aria-label="Permalink to &quot;读懂触发结果&quot;">​</a></h2><p>成功通过认证和参数校验的 Webhook、手动轮询都会返回 HTTP <code>202</code>。正文的 <code>status</code> 决定下一步：</p><table tabindex="0"><thead><tr><th><code>status</code></th><th>常见 <code>reason</code></th><th>含义</th></tr></thead><tbody><tr><td><code>queued</code></td><td><code>webhook</code>、<code>poll_detected_change</code> 或发送端给出的事件</td><td>已创建或复用需要 Worker 处理的事实刷新任务</td></tr><tr><td><code>skipped</code></td><td><code>commit_already_analyzed</code></td><td>该分支和提交的事实已经是当前状态</td></tr><tr><td><code>skipped</code></td><td><code>commit_already_queued</code></td><td>相同仓库、分支和提交已有任务在队列中</td></tr><tr><td><code>skipped</code></td><td><code>local_workspace_dirty</code></td><td>本地工作区有未提交修改，轮询不会把它当作可复现提交刷新</td></tr><tr><td><code>skipped</code></td><td><code>repository_has_no_git_commit</code></td><td>工作区没有可识别的 Git 提交</td></tr></tbody></table><p><code>queued</code> 结果会带 <code>run_id</code>。继续在运行页面或 MCP 的 <code>get_run_status</code> 中观察它；只有进入完成状态，并且仓库的目录、代码、关系与搜索状态已更新，才算本次自动刷新结束。</p><h2 id="上线前做一次闭环验证" tabindex="-1">上线前做一次闭环验证 <a class="header-anchor" href="#上线前做一次闭环验证" aria-label="Permalink to &quot;上线前做一次闭环验证&quot;">​</a></h2><p>下面是建议检查步骤，不代表已经替你执行：</p><ol><li>保存触发设置，再读取一次，确认启用状态、Cron 和 <code>has_webhook_secret</code> 符合预期。</li><li>对一个已知提交执行手动轮询，或发送一条正确签名的测试 Webhook。</li><li>确认 HTTP 结果是 <code>queued</code>，或是原因符合预期的 <code>skipped</code>。</li><li>对 <code>queued</code> 结果确认 Worker 领取了对应 <code>run_id</code>。</li><li>等待任务完成，再检查仓库提交和各层新鲜度。</li><li>重发同一提交，确认返回 <code>commit_already_analyzed</code> 或 <code>commit_already_queued</code>，而不是产生无止境的重复任务。</li></ol><p>如果计划一直不执行，先确认 <code>ershu-api-poller</code> 是独立运行的，再检查 Redis、UTC Cron 和仓库凭据。API Web 进程本身不会代为执行计划。</p><blockquote><p>主要源码位置：<code>api/src/ershu/api/poller.py</code>、<code>api/src/ershu/api/services/repositories/triggers.py</code>、<code>api/src/ershu/api/routes/projects/repositories.py</code>、<code>core/src/ershu/services/runs/fact_refresh.py</code>。</p></blockquote>`,39)])])}const b=t(o,[["render",i]]);export{u as __pageData,b as default};
